def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find horizontal bands of non-background pattern.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # A repeated band may be shifted horizontally and clipped at the right.
    for i, (a, b) in enumerate(bands):
        height = b - a
        for c0, d in bands[i + 1:]:
            if d - c0 != height:
                continue

            best_shift, best_score = 0, 0
            for shift in range(-8, 9):
                inter = union = 0
                for k in range(height):
                    for col in range(w):
                        x = col - shift
                        src = 0 <= x < w and grid[a + k][x] != bg
                        dst = grid[c0 + k][col] != bg
                        inter += src and dst
                        union += src or dst
                score = inter / union if union else 0
                if score > best_score:
                    best_shift, best_score = shift, score

            if best_score < 0.55 or best_shift <= 0:
                continue

            for k in range(height):
                rr = c0 + k
                last = max((col for col, v in enumerate(grid[rr]) if v != bg),
                           default=-1)
                for col in range(last + 1, w):
                    src_col = col - best_shift
                    if 0 <= src_col < w and grid[a + k][src_col] != bg:
                        out[rr][col] = 1

            return out

    # Fallback: extend the rightmost foreground pixels in each band.
    for start, end in bands:
        edge = max(col for rr in range(start, end)
                   for col, v in enumerate(grid[rr]) if v != bg)
        for rr in range(start, end):
            if grid[rr][edge] != bg:
                for col in range(edge + 1, w):
                    out[rr][col] = 1

    return out
